def hairpins(seq,minstem=6,maxloop=40):
    N=len(seq); res=[]
    for i in range(N):
        for L in range(minstem, 20):
            if i+2*L+3 > N: break
            # loop from 3 to maxloop
            for loop in range(3,maxloop+1):
                j=i+L+loop
                if j+L>N: break
                if seq[j:j+L]==rc(seq[i:i+L]):
                    # extend
                    res.append((L,loop,i,j))
    return res
